namespace UniversityCourseCatalog.Models;

public class Department
{
    public string Id { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public string Id { get; set; } = string.Empty;
    public string DepartmentId { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string CourseCode { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string Instructor { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    public string CourseId { get; set; } = string.Empty;
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments =
        [
            new Department { Id = "cs", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new Department { Id = "math", Name = "Mathematics", Description = "Pure and applied mathematics including statistics and data science." },
            new Department { Id = "eng", Name = "English", Description = "Literature, writing, and rhetoric." },
            new Department { Id = "phys", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new Department { Id = "hist", Name = "History", Description = "Exploration of past events, civilizations, and historical analysis." },
        ];

        _courses =
        [
            new Course
            {
                Id = "cs101", DepartmentId = "cs", Title = "Introduction to Programming",
                CourseCode = "CS 101", Description = "Fundamentals of programming using Python. Covers variables, control flow, functions, and basic data structures.",
                Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Instructor = "Dr. Sarah Chen",
                InstructorBio = "Dr. Chen specializes in programming language design and computer science education. She has 15 years of teaching experience.",
                IsFeatured = true
            },
            new Course
            {
                Id = "cs201", DepartmentId = "cs", Title = "Data Structures & Algorithms",
                CourseCode = "CS 201", Description = "In-depth study of data structures (trees, graphs, hash tables) and algorithm design techniques.",
                Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", Instructor = "Dr. James Park",
                InstructorBio = "Dr. Park's research focuses on algorithm optimization and computational complexity theory.",
                IsFeatured = false
            },
            new Course
            {
                Id = "cs310", DepartmentId = "cs", Title = "Database Systems",
                CourseCode = "CS 310", Description = "Relational database design, SQL, transaction processing, and introduction to NoSQL systems.",
                Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", Instructor = "Dr. Maria Lopez",
                InstructorBio = "Dr. Lopez has industry experience at major tech companies and specializes in distributed database systems.",
                IsFeatured = true
            },
            new Course
            {
                Id = "math101", DepartmentId = "math", Title = "Calculus I",
                CourseCode = "MATH 101", Description = "Limits, derivatives, and integrals of single-variable functions with applications.",
                Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Instructor = "Dr. Robert Kim",
                InstructorBio = "Dr. Kim is an award-winning educator known for making calculus accessible to all students.",
                IsFeatured = true
            },
            new Course
            {
                Id = "math250", DepartmentId = "math", Title = "Linear Algebra",
                CourseCode = "MATH 250", Description = "Vector spaces, matrices, linear transformations, eigenvalues, and applications.",
                Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", Instructor = "Dr. Emily Zhang",
                InstructorBio = "Dr. Zhang researches applications of linear algebra in machine learning and data science.",
                IsFeatured = false
            },
            new Course
            {
                Id = "eng101", DepartmentId = "eng", Title = "College Composition",
                CourseCode = "ENG 101", Description = "Development of academic writing skills through essays, research papers, and peer review.",
                Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Instructor = "Prof. David Miller",
                InstructorBio = "Prof. Miller is a published author and writing coach with expertise in rhetoric and composition.",
                IsFeatured = false
            },
            new Course
            {
                Id = "eng220", DepartmentId = "eng", Title = "American Literature",
                CourseCode = "ENG 220", Description = "Survey of American literature from the colonial period to the present day.",
                Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", Instructor = "Dr. Angela Torres",
                InstructorBio = "Dr. Torres specializes in 20th-century American fiction and has published extensively on the Harlem Renaissance.",
                IsFeatured = true
            },
            new Course
            {
                Id = "phys101", DepartmentId = "phys", Title = "General Physics I",
                CourseCode = "PHYS 101", Description = "Mechanics, thermodynamics, and waves. Includes laboratory sessions.",
                Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Thu Lab 2:00–4:00 PM", Instructor = "Dr. Alan Foster",
                InstructorBio = "Dr. Foster's research in experimental physics spans condensed matter and materials science.",
                IsFeatured = false
            },
            new Course
            {
                Id = "hist101", DepartmentId = "hist", Title = "World History to 1500",
                CourseCode = "HIST 101", Description = "Survey of world civilizations from ancient times through the late medieval period.",
                Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:15 PM", Instructor = "Dr. Patricia Wells",
                InstructorBio = "Dr. Wells is a specialist in ancient Mediterranean civilizations and has led archaeological expeditions.",
                IsFeatured = false
            },
            new Course
            {
                Id = "hist205", DepartmentId = "hist", Title = "Modern European History",
                CourseCode = "HIST 205", Description = "Europe from the French Revolution to the present, covering political, social, and cultural developments.",
                Credits = 3, Schedule = "Mon/Wed 3:30–4:45 PM", Instructor = "Dr. Thomas Grant",
                InstructorBio = "Dr. Grant is an expert on 19th-century European nationalism and has authored three books on the subject.",
                IsFeatured = false
            },
        ];
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(string id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? searchTerm = null, string? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(departmentId))
        {
            query = query.Where(c => c.DepartmentId == departmentId);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Instructor.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(string id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();
}

